import {CABLES,DEVICES,trainingLayout,feedbackPose} from './story-training.js';
import {t} from './strings.js';
const upper=s=>s[0].toUpperCase()+s.slice(1);
const colours=['Red','Black','Orange','Grey'];
export function cableLabel(c,socket=false){return t(socket?'upgradeSocketLabel':'upgradePlugLabel',{panel:c.panel,colour:t('upgradeColour'+colours[CABLES.findIndex(x=>x.id===c.id)]),shape:t('upgradeShape'+upper(c.shape)),sign:t(c.sign==='+'?'upgradePositive':'upgradeNegative')});}
export function plugShape(c){const shape={circle:'<circle cx="16" cy="16" r="11"/>',square:'<rect x="5" y="5" width="22" height="22" rx="1"/>',triangle:'<path d="M16 3 30 28H2Z"/>',diamond:'<path d="m16 2 14 14-14 14L2 16Z"/>'}[c.shape];return `<svg viewBox="0 0 32 32" aria-hidden="true" style="--plug-colour:${c.color}">${shape}</svg><span aria-hidden="true">${c.sign}</span>`;}
export function createStoryControls({element,canvas,getState,isPaused,reduced=()=>false,onAttempt,onHint}){
 let scene='',selected=null,drag=null,skipClick=0,layout=null,signature='',wasAnimating=false;
 const port=(id,x,y,source,label,html='')=>`<button type="button" class="training-port ${source?'loose-plug':'machine-port'}" data-${source?'source':'socket'}="${id}" style="left:${x}px;top:${y}px" aria-label="${label}" title="${label}" ${source?'aria-pressed="false"':''}>${html}</button>`;
 function build(){const s=getState();if(!s||!['connect','power'].includes(s.scene))return;const r=canvas.getBoundingClientRect(),sig=s.scene+s.socketOrder.join(',')+JSON.stringify(s.scene==='connect'?s.cables:s.power)+selected+Boolean(s.transition)+r.width+':'+r.height,anim=s.feedback.kind==='happy'&&s.feedback.age<.7;if(sig===signature&&!anim&&!wasAnimating)return;wasAnimating=anim;signature=sig;layout=trainingLayout(r.width,r.height,s.scene,s.socketOrder);element.style.left=layout.left+'px';element.style.top=layout.top+'px';element.style.width=layout.width+'px';element.style.height=layout.height+'px';
  if(scene!==s.scene){scene=s.scene;selected=null;drag=null;element.setAttribute('aria-label',t(scene==='connect'?'upgradeConnect':'upgradePowerAir'));element.innerHTML=(scene==='connect'?layout.sources.map(c=>port(c.id,c.x,c.y,true,cableLabel(c),plugShape(c))).join(''):layout.sources.map((c,i)=>port(c.id,c.x,c.y,true,t('upgradeCellLabel',{n:i+1}),'<span aria-hidden="true">⚡</span>')).join(''))+layout.targets.map(c=>port(c.id,c.x,c.y,false,scene==='connect'?cableLabel(c,true):t('upgrade'+upper(c.id)+'Name'),scene==='connect'?plugShape(c):'')).join('');}
  for(const b of element.querySelectorAll('[data-source]')){const p=layout.sources.find(c=>c.id===b.dataset.source);b.style.left=p.x+'px';b.style.top=p.y+'px';const on=scene==='connect'?s.cables[p.id]:!!s.power.ports[p.id];b.disabled=on||s.transition>0;b.classList.toggle('plugged',on);b.classList.toggle('selected',selected===p.id);b.setAttribute('aria-pressed',String(selected===p.id));}
  for(const b of element.querySelectorAll('[data-socket]')){const p=layout.targets.find(c=>c.id===b.dataset.socket),on=scene==='connect'?s.cables[p.id]:s.power[p.id];b.style.left=p.x+'px';b.style.top=p.y+'px';b.disabled=!!on||s.transition>0;b.classList.toggle('plugged',!!on);const pfx=s.feedback.target===p.id&&s.feedback.kind==='happy'?feedbackPose(s.feedback.age,reduced()):{scale:1,angle:0};b.style.transform=`translate(-50%,-50%) scale(${pfx.scale}) rotate(${pfx.angle}rad)`;if(scene==='power')b.classList.add('device-target');}
 }
 function oops(from,id){const sock=element.querySelector(`[data-socket="${id}"]`),src=element.querySelector(`[data-source="${from}"]`);if(!sock||sock.disabled)return;
  for(const b of [sock,src]){if(!b)continue;b.classList.remove('wrong');void b.offsetWidth;b.classList.add('wrong');setTimeout(()=>b.classList.remove('wrong'),650);}
  element.querySelector('.oops-bubble')?.remove();const tip=document.createElement('span');tip.className='oops-bubble';tip.setAttribute('aria-hidden','true');tip.textContent=t('oopsTry');tip.style.left=sock.style.left;tip.style.top=sock.style.top;element.append(tip);setTimeout(()=>tip.remove(),1400);}
 function select(id){selected=id;build();onHint(scene==='connect'?'upgradeSelected':'upgradeBatterySelected',false);}
 function attempt(id){if(!selected){onHint(scene==='connect'?'upgradeSelectCable':'upgradeSelectBattery',true);return;}const from=selected,ok=onAttempt(from,id);if(ok)selected=null;build();if(!ok)oops(from,id);if(ok){const next=element.querySelector('[data-source]:not(:disabled)');next?.focus({preventScroll:true});}}
 element.addEventListener('click',e=>{if(isPaused()||performance.now()<skipClick)return;const b=e.target.closest('button');if(!b)return;if(b.dataset.source)select(b.dataset.source);else if(b.dataset.socket)attempt(b.dataset.socket);});
 element.addEventListener('pointerdown',e=>{if(isPaused())return;const b=e.target.closest('[data-source]');if(!b||b.disabled)return;selected=b.dataset.source;drag={source:selected,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};b.setPointerCapture(e.pointerId);build();});
 function move(e){if(!drag||isPaused())return;drag.x=e.clientX;drag.y=e.clientY;drag.moved||=Math.hypot(drag.x-drag.startX,drag.y-drag.startY)>6;}
 function up(e){if(!drag)return;const moved=drag.moved;drag=null;if(isPaused())return;if(moved){skipClick=performance.now()+200;const b=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-socket]');if(b&&!b.disabled)attempt(b.dataset.socket);else build();}}
 window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',()=>{drag=null;});
 return{render:build,reset(){scene='';selected=null;drag=null;signature='';},cancel(){drag=null;selected=null;build();},visual(){const r=canvas.getBoundingClientRect();return{layout,selected,drag:drag&&drag.moved?{x:drag.x-r.left,y:drag.y-r.top}:null};}};
}

export function bindStoryVisibility(doc,win,pause){const hidden=()=>{if(doc.hidden)pause();};const blur=()=>pause();doc.addEventListener('visibilitychange',hidden);win.addEventListener('blur',blur);return()=>{doc.removeEventListener('visibilitychange',hidden);win.removeEventListener('blur',blur);};}
